try (java.io.InputStream is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(grid_png));
     java.io.ByteArrayOutputStream os = new java.io.ByteArrayOutputStream()) {

    net.coobird.thumbnailator.Thumbnailator.createThumbnail(is, os, "png", 50, 50);

    byte[] resultBytes = os.toByteArray();
    assert resultBytes.length > 0 : "Output stream should not be empty";

    try (java.io.InputStream resultIs = new java.io.ByteArrayInputStream(resultBytes)) {
        java.awt.image.BufferedImage resultImage = javax.imageio.ImageIO.read(resultIs);
        assert resultImage != null : "Resulting image should be readable";
        assert resultImage.getWidth() <= 50 && resultImage.getHeight() <= 50 : "Image dimensions should be within 50x50";

        System.out.println("__CHECK__ createThumbnail " + resultImage.getWidth() + "x" + resultImage.getHeight());
    }
} catch (java.io.IOException e) {
    throw new RuntimeException(e);
}

